<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Disease Statistics | TABACARE</title>
    <script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.js"></script>
    <style>
        .sidebar { position: sticky; top: 0; height: 100vh; }
        :root{--ink:#1d2935;--muted:#70808b;--paper:#f4f7f8;--panel:#fff;--line:#e1e8eb;--teal:#0f766e;--nav:#172331;--shadow:0 14px 36px rgba(27,45,61,.08)}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:Georgia,'Times New Roman',serif}.shell{min-height:100vh;display:grid;grid-template-columns:260px 1fr}.sidebar{display:flex;flex-direction:column;min-height:100vh;padding:22px 13px;background:var(--nav);color:#d9e3ea}.brand{display:flex;align-items:center;gap:11px;padding:5px 12px 28px;border-bottom:1px solid rgba(255,255,255,.08)}.mark{width:38px;height:38px;display:grid;place-items:center;border:1px solid rgba(255,255,255,.4);border-radius:10px;color:#70ddd0;font:24px Arial}.brand strong{display:block;color:#fff;font:800 16px Arial;letter-spacing:.08em}.brand small{color:#91a7b5;font:10px Arial;letter-spacing:.08em;text-transform:uppercase}.label{padding:25px 12px 9px;color:#8094a2;font:700 10px Arial;letter-spacing:.13em;text-transform:uppercase}.nav{display:grid;gap:5px}.nav a{display:flex;align-items:center;gap:11px;padding:12px;border-radius:8px;color:#aabac5;text-decoration:none;font:600 14px Arial}.nav a:hover,.nav a.active{background:rgba(20,184,166,.14);color:#6ee7d8}.nav-icon{width:20px;text-align:center}.side-footer{margin-top:auto;padding:16px 12px 4px;border-top:1px solid rgba(255,255,255,.08);color:#8da1ad;font:12px/1.5 Arial}.main{min-width:0;padding:30px clamp(20px,4vw,58px) 48px}.topbar{display:flex;justify-content:space-between;gap:20px;margin-bottom:28px}.eyebrow{color:var(--teal);font:700 11px Arial;letter-spacing:.16em;text-transform:uppercase}h1{margin:7px 0 6px;font-size:clamp(28px,4vw,40px);font-weight:400}.intro{margin:0;color:var(--muted);font-size:16px}.profile{display:flex;align-items:center;gap:10px;color:var(--muted);font:13px Arial}.avatar{width:39px;height:39px;display:grid;place-items:center;border-radius:50%;background:#f2d18b;color:#65491a;font-weight:700}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-bottom:18px}.summary-card{padding:20px;background:var(--panel);border:1px solid var(--line);box-shadow:var(--shadow)}.summary-card.alert{border-color:#fecaca;background:#fff5f5}.summary-label{display:block;color:var(--muted);font:700 10px Arial;letter-spacing:.1em;text-transform:uppercase}.summary-value{display:block;margin-top:12px;color:var(--teal);font-size:32px}.alert .summary-value{color:#b91c1c}.notice{display:flex;gap:12px;margin-bottom:18px;padding:16px;border:1px solid #fecaca;border-radius:7px;background:#fff1f2;color:#881337;font:13px/1.5 Arial}.notice.ok{border-color:#bbf7d0;background:#f0fdf4;color:#166534}.notice strong{display:block;margin-bottom:3px}.cards{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-bottom:18px}.disease-card{padding:17px;border-radius:6px;color:#fff;box-shadow:var(--shadow)}.disease-card h3{margin:0 0 10px;font:600 12px Arial;opacity:.9}.disease-card strong{font-size:29px}.disease-card small{display:block;margin-top:7px;font:11px Arial;opacity:.9}.green{background:#16a34a}.gold{background:#ca8a04}.orange{background:#ea580c}.purple{background:#7c3aed}.red{background:#dc2626}.panel{padding:22px;background:var(--panel);border:1px solid var(--line);box-shadow:var(--shadow);margin-bottom:18px}.panel-head{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-bottom:17px}.panel h2{margin:0;font-size:19px;font-weight:400}.filter{display:flex;align-items:center;gap:8px;font:700 11px Arial;color:var(--muted)}select{padding:9px;border:1px solid var(--line);border-radius:4px;background:#fff;color:var(--ink)}.chart{height:340px}.charts{display:grid;grid-template-columns:1fr 1fr;gap:18px}.chart.tall{height:410px}.chart-note{color:var(--muted);font:12px Arial}@media(max-width:1000px){.cards{grid-template-columns:repeat(3,1fr)}.charts{grid-template-columns:1fr}}@media(max-width:850px){.shell{grid-template-columns:1fr}.sidebar{min-height:auto;padding:14px 18px}.brand{padding:0 0 14px;border:0}.label,.side-footer{display:none}.nav{display:flex;overflow-x:auto}.nav a{white-space:nowrap}}@media(max-width:600px){.topbar{display:block}.profile{margin-top:16px}.summary,.cards{grid-template-columns:1fr}.panel-head{align-items:flex-start;flex-direction:column}.filter{width:100%;justify-content:space-between}}
        .insight-grid{display:grid;grid-template-columns:1.2fr .8fr;gap:18px;margin-bottom:18px}.insight-card{padding:22px;background:var(--panel);border:1px solid var(--line);box-shadow:var(--shadow)}.insight-card h2{margin:0 0 16px;font-size:19px;font-weight:400}.trend-chart{height:250px}.comparison{display:flex;align-items:center;gap:14px;margin-bottom:18px;padding:14px;border-radius:8px;background:#f0fdfa;color:var(--teal);font:13px Arial}.comparison strong{font-size:25px}.comparison.down{background:#fff7ed;color:#c2410c}.comparison.flat{background:#f8fafc;color:var(--muted)}.rank-list{display:grid;gap:13px}.rank-row{display:grid;grid-template-columns:22px 1fr auto;align-items:center;gap:9px;font:13px Arial}.rank-number{color:var(--teal);font-weight:700}.rank-track{height:7px;margin-top:6px;border-radius:5px;background:#edf2f3;overflow:hidden}.rank-fill{height:100%;border-radius:5px;background:var(--teal)}@media(max-width:800px){.insight-grid{grid-template-columns:1fr}}
        .charts{display:block}.charts .panel{margin-bottom:22px}.charts .chart{height:360px}.charts .chart.tall{height:520px;overflow:hidden}.charts .chart.tall canvas{display:block;width:100%!important;height:520px!important}.charts .panel-head h2{font-size:20px}.charts .chart-note{font-size:12px}@media(max-width:600px){.charts .chart{height:340px}.charts .chart.tall{height:520px}.charts .chart.tall canvas{height:520px!important}}
        .barangay-chart-scroll{height:520px;overflow-y:auto;overflow-x:hidden}.charts .chart.tall.dynamic-chart{overflow:visible}.charts .chart.tall.dynamic-chart canvas{height:100%!important}
        .mark img{width:38px;height:38px;object-fit:contain;border-radius:10px;background:#fff}
    </style>
</head>
<body>
<div class="shell">
    <aside class="sidebar"><div class="brand"><div class="mark"><img src="{{ asset('images/tabacare-logo.png') }}" alt="TABACARE logo"></div><div><strong>TABACARE</strong><small>Administration</small></div></div><div class="label">Management</div><nav class="nav"><a href="{{ route('admin.dashboard') }}"><span class="nav-icon">&#9632;</span> Dashboard</a><a href="{{ route('admin.accounts') }}"><span class="nav-icon">&#9673;</span> Barangay accounts</a><a href="{{ route('admin.reports') }}"><span class="nav-icon">&#9776;</span> Barangay reports</a><a class="active" href="{{ route('admin.statistics') }}"><span class="nav-icon">&#9646;</span> Disease statistics</a><a href="{{ route('admin.patients') }}"><span class="nav-icon">&#9998;</span> List of patients</a></nav><div class="side-footer">Administrator access<br><strong>{{ $adminName }}</strong><a href="{{ route('admin.admin-accounts.index') }}" style="display:block;margin-top:12px;padding:9px 10px;border-radius:6px;background:rgba(255,255,255,.08);color:#d9e3ea;text-decoration:none;font:600 12px Arial">Admin accounts</a><form method="POST" action="{{ route('logout') }}" style="margin-top:12px">@csrf<button type="submit" style="width:100%;padding:9px;border:1px solid #dcebea;border-radius:6px;background:transparent;color:#aabac5;cursor:pointer;font:600 12px Arial">Log out</button></form></div></aside>
    <main class="main">
        <header class="topbar"><div><div class="eyebrow">Administration workspace</div><h1>Disease statistics</h1><p class="intro">A city-wide view of recorded cases across Tabaco City.</p></div><div class="profile"><div class="avatar">{{ strtoupper(substr($adminName,0,1)) }}</div>{{ $adminName }}</div></header>
        <section class="summary"><article class="summary-card"><span class="summary-label">Total recorded patients</span><span class="summary-value">{{ $totalPatients }}</span></article><article class="summary-card"><span class="summary-label">Cases in {{ $monthLabel }}</span><span class="summary-value">{{ $monthlyTotal }}</span></article><article class="summary-card alert"><span class="summary-label">Possible outbreaks by disease</span><span class="summary-value">{{ $outbreakAlerts->count() }}</span>@if($outbreakAlerts->isNotEmpty())<div style="margin-top:10px;color:#881337;font:12px/1.5 Arial">@foreach($outbreakAlerts as $disease => $total)<div><strong>{{ $disease }}</strong>: {{ $total }} cases</div>@endforeach</div>@else<div style="margin-top:10px;color:var(--muted);font:12px Arial">No diseases at alert level</div>@endif</article></section>
        @php($comparisonClass = $monthChange > 0 ? '' : ($monthChange < 0 ? 'down' : 'flat'))
        <section class="insight-grid">
            <article class="insight-card"><h2>Six-month case trend</h2><div class="trend-chart"><canvas id="trendChart"></canvas></div></article>
            <article class="insight-card"><h2>Highest-case barangays</h2><div class="comparison {{ $comparisonClass }}"><strong>{{ $monthChange > 0 ? '+' : '' }}{{ $monthChange }}%</strong><span>vs. last month<br><small>{{ $previousMonthTotal }} cases last month</small></span></div><div class="rank-list">@forelse($topBarangays as $barangay => $count)<div class="rank-row"><span class="rank-number">{{ $loop->iteration }}</span><div>{{ $barangay }}<div class="rank-track"><div class="rank-fill" style="width:{{ $topBarangays->first() > 0 ? round(($count / $topBarangays->first()) * 100) : 0 }}%"></div></div></div><strong>{{ $count }}</strong></div>@empty<span class="chart-note">No patient records yet.</span>@endforelse</div></article>
        </section>
        @if($outbreakAlerts->isNotEmpty())<div class="notice"><div>!</div><div><strong>Possible disease outbreak detected</strong>{{ $outbreakAlerts->map(fn($total,$disease) => $disease.' ('.$total.' cases)')->implode(', ') }} reached the alert level of {{ $outbreakThreshold }} cases this month.</div></div>@else<div class="notice ok">No disease has reached the {{ $outbreakThreshold }}-case monthly alert level for {{ $monthLabel }}.</div>@endif
        <section class="cards">@php($colors=['green','gold','orange','purple','red'])@foreach($diseases as $index => $disease)<article class="disease-card {{ $colors[$index] }}"><h3>{{ $disease }}</h3><strong>{{ $diseaseCounts[$disease] }}</strong><small>{{ $monthlyCases[$disease] ?? 0 }} this month</small></article>@endforeach</section>
        <div class="charts"><section class="panel"><div class="panel-head"><h2>Patients by disease</h2><span class="chart-note">All barangays</span></div><div class="chart"><canvas id="diseaseChart"></canvas></div></section><section class="panel" id="patients-by-barangay"><div class="panel-head"><div><h2>Patients by barangay</h2><span class="chart-note">Ranked highest to lowest · Scroll to see all barangays</span></div><form class="filter" method="GET" action="{{ route('admin.statistics') }}#patients-by-barangay"><label for="diseaseFilter">Disease</label><select id="diseaseFilter" name="barangay_disease" onchange="this.form.submit()"><option value="">All diseases</option>@foreach($diseases as $disease)<option value="{{ $disease }}" @selected($filter === $disease)>{{ $disease }}</option>@endforeach</select></form></div><div class="barangay-chart-scroll"><div class="chart tall dynamic-chart" style="height:{{ max(520, $barangayChartData->count() * 28) }}px"><canvas id="barangayChart"></canvas></div></div></section></div>
    </main>
</div>
<script>
const diseasePalette=['#22c55e','#eab308','#f97316','#8b5cf6','#ef4444'];
const diseaseColorByName=Object.fromEntries(@json($diseases).map((disease,index)=>[disease,diseasePalette[index%diseasePalette.length]]));
const selectedDisease=@json($filter);
const selectedDiseaseColor=diseaseColorByName[selectedDisease]||'#0f766e';
new Chart(document.getElementById('diseaseChart'),{type:'bar',data:{labels:@json($diseases),datasets:[{label:'Patients',data:@json($diseaseCounts->values()),backgroundColor:diseasePalette,borderRadius:5,borderSkipped:false}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{callbacks:{label:(ctx)=>'Patients: '+ctx.parsed.y}}},scales:{y:{beginAtZero:true,ticks:{stepSize:1},title:{display:true,text:'Patients'}},x:{grid:{display:false},ticks:{autoSkip:false,maxRotation:35,minRotation:0}}}}});
new Chart(document.getElementById('barangayChart'),{type:'bar',data:{labels:@json($barangayChartData->keys()->values()),datasets:[{label:@json($filter ? $filter.' patients' : 'All patients'),data:@json($barangayChartData->values()),backgroundColor:selectedDiseaseColor,hoverBackgroundColor:selectedDiseaseColor,borderRadius:3,borderSkipped:false,barThickness:8}]},options:{indexAxis:'y',responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{callbacks:{label:(ctx)=>'Patients: '+ctx.parsed.x}}},scales:{x:{beginAtZero:true,ticks:{stepSize:1,font:{size:10}},title:{display:true,text:'Patients',font:{size:11}},grid:{color:'#e5eeee'}},y:{title:{display:true,text:'Barangay',font:{size:11}},grid:{display:false},ticks:{font:{size:11},autoSkip:false,padding:8}}}}});
new Chart(document.getElementById('trendChart'),{type:'line',data:{labels:@json($trendLabels),datasets:[{label:'Cases',data:@json($trendValues),borderColor:'#0f766e',backgroundColor:'rgba(15,118,110,.12)',fill:true,tension:.35,pointRadius:4,pointBackgroundColor:'#0f766e'}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,ticks:{stepSize:1}},x:{grid:{display:false}}}}});
</script>
@include('partials.submit-guard')
</body>
</html>
